let line;
while ((line = readLine()) !== null) lines.push(line);
const [s, t] = lines.join(' ').split(/\s+/).filter(x => x.length);
const n = s.length, m = t.length;
let prev = Array.from({ length: m + 1 }, (_, j) => j);
for (let i = 1; i <= n; i++) {
  const cur = new Array(m + 1).fill(0);
  cur[0] = i;
  for (let j = 1; j <= m; j++) {
    cur[j] = Math.min(prev[j] + 1, cur[j - 1] + 1, prev[j - 1] + (s[i - 1] !== t[j - 1] ? 1 : 0));
  }
  prev = cur;
}
console.log(prev[m]);

solutions.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String s = sc.next(), t = sc.next();
        int n = s.length(), m = t.length();
        int[] prev = new int[m + 1];
        for (int j = 0; j <= m; j++) prev[j] = j;
        for (int i = 1; i <= n; i++) {
            int[] cur = new int[m + 1];
            cur[0] = i;
            for (int j = 1; j <= m; j++) {
                int rep = prev[j - 1] + (s.charAt(i - 1) != t.charAt(j - 1) ? 1 : 0);
                cur[j] = Math.min(rep, Math.min(prev[j] + 1, cur[j - 1] + 1));
            }
            prev = cur;
        }
        System.out.println(prev[m]);
    }
}

