#include <bits/stdc++.h>
using namespace std;
int main() {
    string s, t;
    cin >> s >> t;
    int n = s.size(), m = t.size();
    vector<int> prev(m + 1), cur(m + 1);
    iota(prev.begin(), prev.end(), 0);
    for (int i = 1; i <= n; i++) {
        cur[0] = i;
        for (int j = 1; j <= m; j++) {
            int rep = prev[j - 1] + (s[i - 1] != t[j - 1]);
            cur[j] = min(rep, min(prev[j] + 1, cur[j - 1] + 1));
        }
        swap(prev, cur);
    }
    printf("%d\n", prev[m]);
    return 0;
}
